const cfg = $('Set Workflow Configuration').item.json;

// Prefer the original trigger payload (Set node only carries config values)
let raw = {};
try {
  const wh = $('Receive Policy Question').item.json;
  raw = wh.body || wh;
} catch (e) {
  try {
    raw = $('Manual Test Trigger').item.json;
  } catch (e2) {
    raw = $json.body || $json;
  }
}

const message = String(raw.message || raw.question || raw.query || '').trim();
const userId = String(raw.userId || raw.user_id || raw.employeeId || 'anonymous').trim();
const channel = String(raw.channel || 'webhook').trim().toLowerCase();
const sessionId = String(raw.sessionId || raw.session_id || `sess_${Date.now()}`).trim();
const department = String(raw.department || raw.dept || '').trim();
const purchaseAmount = raw.purchaseAmount != null ? Number(raw.purchaseAmount) : null;

const validation_errors = [];
if (!message) validation_errors.push('Missing required field: message');
else if (message.length < 5) validation_errors.push('message must be at least 5 characters');
else if (message.length > 2000) validation_errors.push('message must be 2000 characters or fewer');

if (purchaseAmount != null && (Number.isNaN(purchaseAmount) || purchaseAmount < 0)) {
  validation_errors.push('purchaseAmount must be a non-negative number when provided');
}

return [{
  json: {
    message,
    userId,
    channel,
    sessionId,
    department,
    purchaseAmount,
    timestamp: new Date().toISOString(),
    is_valid: validation_errors.length === 0,
    validation_errors,
    confidence_threshold: Number(cfg.CONFIDENCE_THRESHOLD || 0.70),
    company_name: cfg.COMPANY_NAME || 'Your Company',
    policy_pdf_url: cfg.POLICY_PDF_URL,
    helpdesk_url: cfg.HELPDESK_TICKET_URL,
    slack_webhook_url: cfg.SLACK_WEBHOOK_URL,
    audit_sheet_id: cfg.AUDIT_SHEET_ID,
    support_email: cfg.SUPPORT_EMAIL || 'user@example.com'
  }
}];

