const text = String($json.text || '');
const lower = text.toLowerCase();

const domainScores = {
  procurement: (lower.match(/\b(purchase|vendor|supplier|procurement|bid|rfp|contract|invoice|purchase order|\bpo\b)\b/g) || []).length,
  hr: (lower.match(/\b(employee|leave|holiday|disciplinary|grievance|recruitment|probation|salary|benefits)\b/g) || []).length,
  it_security: (lower.match(/\b(password|data breach|gdpr|cybersecurity|access control|encryption|incident)\b/g) || []).length,
  finance: (lower.match(/\b(expense|budget|reimbursement|payment|audit|tax|fiscal|accounting|capex)\b/g) || []).length,
  legal: (lower.match(/\b(compliance|regulation|liability|indemnity|confidentiality|nda|jurisdiction)\b/g) || []).length,
  health_safety: (lower.match(/\b(safety|hazard|risk assessment|accident|ppe|first aid|evacuation)\b/g) || []).length,
};
const domain = Object.entries(domainScores).sort((a, b) => b[1] - a[1])[0][0];

const hasNumberedSections = /^\s*\d+[\.\)]\s+\w/m.test(text);
const hasBulletLists = /^\s*[•\-\*]\s+\w/m.test(text);
const hasFAQStyle = /\b(q:|q\.|question:|faq)\b/i.test(text);
const hasAllCapsHeaders = /^[A-Z][A-Z\s]{4,}$/m.test(text);

let structureType = 'general narrative';
if (hasNumberedSections) structureType = 'numbered sections';
else if (hasFAQStyle) structureType = 'FAQ format';
else if (hasBulletLists) structureType = 'bullet-list heavy';
else if (hasAllCapsHeaders) structureType = 'all-caps section headers';

const hasApprovalLimits = /\b(\$[\d,]+|£[\d,]+|€[\d,]+|\d+\s*(usd|gbp|eur)|approval limit|authorize|authorise)\b/i.test(text);
const hasPenalties = /\b(penalty|penalt|terminat|disciplin|dismiss|warning|consequence)\b/i.test(text);
const hasForms = /\b(form [a-z0-9\-]+|submit a form|complete the form)\b/i.test(text);

const lines = text.split('\n').map(l => l.trim()).filter(l => l.length > 4);
const titleLine = lines.find(l => /policy|manual|handbook|procedure|guideline/i.test(l) && l.length < 120) || lines[0] || 'Company Policy Document';

const req = $('Normalize & Validate Request').item.json;

return [{
  json: {
    domain,
    domainScores,
    structureType,
    hasApprovalLimits,
    hasPenalties,
    hasForms,
    docTitle: titleLine.substring(0, 100),
    sectionCount: (text.match(/^\s*\d+[\.\)]/mg) || []).length,
    policyText: text,
    charCount: text.length,
    message: req.message,
    userId: req.userId,
    channel: req.channel,
    sessionId: req.sessionId,
    department: req.department,
    purchaseAmount: req.purchaseAmount,
    timestamp: req.timestamp,
    confidence_threshold: req.confidence_threshold,
    company_name: req.company_name,
    helpdesk_url: req.helpdesk_url,
    slack_webhook_url: req.slack_webhook_url,
    audit_sheet_id: req.audit_sheet_id,
    support_email: req.support_email
  }
}];

const q = String($json.message || '').toLowerCase();
const scores = {
  APPROVAL_LIMITS: (q.match(/\b(approv|threshold|limit|authority|sign.?off|delegate|manager|director|cfo|budget)\b/g) || []).length,
  VENDOR_SELECTION: (q.match(/\b(vendor|supplier|preferred|sole.?source|rfp|rfq|bid|quote|marketplace)\b/g) || []).length,
  PURCHASE_ORDER: (q.match(/\b(purchase order|\bpo\b|requisition|pr\b|ordering|catalog|guided buying)\b/g) || []).length,
  CONTRACTS: (q.match(/\b(contract|msa|nda|sow|amendment|renewal|legal review|clause)\b/g) || []).length,
  GENERAL_POLICY: 1
};

let intent = 'GENERAL_POLICY';
let best = 0;
for (const [key, score] of Object.entries(scores)) {
  if (key === 'GENERAL_POLICY') continue;
  if (score > best) {
    best = score;
    intent = key;
  }
}
if (best === 0) intent = 'GENERAL_POLICY';

return [{
  json: {
    ...$json,
    question_intent: intent,
    intent_scores: scores
  }
}];

const policyText = String($json.policyText || '');
const question = String($json.message || '');
const intent = String($json.question_intent || 'GENERAL_POLICY');
const intentHints = String($json.intent_retrieval_hints || '');

const chunks = [];
const rawParts = policyText.split(/\n(?=\s*(?:\d+[\.\)]\s+|[A-Z][A-Z0-9\s&\/\-]{4,}\s*$))/m);
for (const part of rawParts) {
  const cleaned = part.trim();
  if (cleaned.length < 40) continue;
  if (cleaned.length <= 1200) {
    chunks.push(cleaned);
  } else {
    for (let i = 0; i < cleaned.length; i += 1000) {
      chunks.push(cleaned.slice(i, i + 1200));
    }
  }
}
if (chunks.length === 0 && policyText.trim()) {
  chunks.push(policyText.slice(0, 4000));
}

const stop = new Set(['the','a','an','and','or','to','of','in','for','is','are','what','how','when','does','do','can','i','we','my','our','on','with','be','this','that','from','as','at','by']);
const qTokens = `${question} ${intentHints}`.toLowerCase().split(/[^a-z0-9$€£]+/).filter(t => t.length > 2 && !stop.has(t));

function scoreChunk(chunk) {
  const lower = chunk.toLowerCase();
  let score = 0;
  for (const t of qTokens) {
    if (lower.includes(t)) score += 2;
  }
  if (intent === 'APPROVAL_LIMITS' && /approv|threshold|limit|\$|€|£/.test(lower)) score += 3;
  if (intent === 'VENDOR_SELECTION' && /vendor|supplier|rfp|preferred/.test(lower)) score += 3;
  if (intent === 'PURCHASE_ORDER' && /purchase order|\bpo\b|requisition/.test(lower)) score += 3;
  if (intent === 'CONTRACTS' && /contract|nda|msa|legal/.test(lower)) score += 3;
  return score;
}

const ranked = chunks
  .map((text, idx) => ({ text, idx, score: scoreChunk(text) }))
  .sort((a, b) => b.score - a.score || a.idx - b.idx);

const top = ranked.slice(0, 5).filter(c => c.score > 0);
const selected = top.length ? top : ranked.slice(0, 3);
const relevantSections = selected.map(c => c.text).join('\n\n---\n\n').slice(0, 12000);
const fallback = policyText.slice(0, 8000);

return [{
  json: {
    ...$json,
    relevantSections: relevantSections || fallback,
    retrievedChunkCount: selected.length,
    retrievalScores: selected.map(c => c.score)
  }
}];

const raw = $input.all()[0].json?.content?.parts?.[0]?.text
  ?? $input.all()[0].json?.text
  ?? $input.all()[0].json?.output
  ?? JSON.stringify($input.all()[0].json ?? {});

let parsed;
try {
  const cleaned = String(raw)
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/\s*```$/i, '')
    .trim();
  parsed = JSON.parse(cleaned);
} catch (e) {
  const ctx = $('Build AI Prompt Context').item.json;
  return [{
    json: {
      answer: 'I was unable to generate a reliable response for this question. Please contact procurement support.',
      confidence: 0,
      policySection: 'Parse error',
      nextAction: `Contact ${ctx.support_email || 'procurement support'}`,
      formOrContact: ctx.support_email || null,
      rulesSummary: null,
      citations: [],
      parseError: true,
      ai_usable: false,
      rawResponse: String(raw).slice(0, 2000),
      question_intent: ctx.question_intent,
      docDomain: ctx.docDomain,
      docTitle: ctx.docTitle,
      message: ctx.userQuestion,
      userId: ctx.userId,
      channel: ctx.channel,
      sessionId: ctx.sessionId,
      department: ctx.department,
      purchaseAmount: ctx.purchaseAmount,
      timestamp: ctx.timestamp,
      confidence_threshold: ctx.confidence_threshold,
      helpdesk_url: ctx.helpdesk_url,
      slack_webhook_url: ctx.slack_webhook_url,
      company_name: ctx.company_name,
      support_email: ctx.support_email
    }
  }];
}

const confidence = typeof parsed.confidence === 'number'
  ? Math.min(1, Math.max(0, parsed.confidence))
  : 0;

const ctx = $('Build AI Prompt Context').item.json;
const answer = parsed.answer || 'No answer generated.';
const ai_usable = Boolean(answer) && answer.length > 10 && !parsed.needs_escalation;

return [{
  json: {
    answer,
    confidence,
    policySection: parsed.policySection || 'Not specified',
    nextAction: parsed.nextAction || `Contact ${ctx.support_email || 'the procurement team'}`,
    formOrContact: parsed.formOrContact || null,
    rulesSummary: parsed.rulesSummary || null,
    citations: Array.isArray(parsed.citations) ? parsed.citations : [],
    parseError: false,
    ai_usable,
    rawResponse: String(raw).slice(0, 2000),
    question_intent: ctx.question_intent,
    docDomain: ctx.docDomain,
    docTitle: ctx.docTitle,
    message: ctx.userQuestion,
    userId: ctx.userId,
    channel: ctx.channel,
    sessionId: ctx.sessionId,
    department: ctx.department,
    purchaseAmount: ctx.purchaseAmount,
    timestamp: ctx.timestamp,
    confidence_threshold: ctx.confidence_threshold,
    helpdesk_url: ctx.helpdesk_url,
    slack_webhook_url: ctx.slack_webhook_url,
    company_name: ctx.company_name,
    support_email: ctx.support_email
  }
}];

