const err = $json;
const execution = err.execution || {};
const error = err.error || {};
const node = err.node || {};

const alert_text = [
  ':rotating_light: *Procurement Policy Helpbot failure*',
  `• Execution ID: ${execution.id || 'unknown'}`,
  `• Failed node: ${node.name || error.node || 'unknown'}`,
  `• Message: ${error.message || err.message || 'Unhandled workflow error'}`,
  `• Time: ${new Date().toISOString()}`
].join('\n');

return [{
  json: {
    alert_text,
    execution_id: execution.id || null,
    failed_node: node.name || null,
    error_message: error.message || err.message || 'Unhandled workflow error',
    timestamp: new Date().toISOString()
  }
}];
